-- create "practice_catalog_signals" table
CREATE TABLE "practice_catalog_signals" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "reason" character varying NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create "practice_subject_catalogs" table
CREATE TABLE "practice_subject_catalogs" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "scope" character varying NOT NULL, "format_version" bigint NOT NULL, "built_at" timestamptz NOT NULL, "items" jsonb NOT NULL, PRIMARY KEY ("id"));
-- create index "practice_subject_catalogs_scope_key" to table: "practice_subject_catalogs"
CREATE UNIQUE INDEX "practice_subject_catalogs_scope_key" ON "practice_subject_catalogs" ("scope");
